arguments.command:
./novamind-operation python-c "
import novamind_api as nm
import inspect

# Check all the function signatures
for module_name in ['pricing', 'marketing', 'analytics', 'enterprise', 'infrastructure', 'market', 'research']:
    mod = getattr(nm, module_name)
    for func_name in [x for x in dir(mod) if not x.startswith('_')]:
        func = getattr(mod, func_name)
        if callable(func):
            try:
                sig = inspect.signature(func)
                print(f'{module_name}.{func_name}{sig}')
            except:
                print(f'{module_name}.{func_name} (no sig)')
" 2>&1

