import novamind_api as nm

# Market overview
overview = nm.market.get_market_overview()
print('=== Market Overview ===')
for key, val in overview.items():
    if key != 'groups':
        print(f'  {key}: {val}')
if 'groups' in overview:
    print('\\n=== Groups ===')
    for g in overview['groups']:
        print(f\"  {g.get('group_id', '?')}: subs={g.get('subscribers', '?')}, cap={g.get('market_cap', '?')}, discovered={g.get('discovered', '?')}\")
"

./novamind-operation python-c "
import novamind_api as nm

# Get detailed group insights for S1
insights = nm.market.get_group_insights(group_id='S1')
print('=== S1 Group Insights ===')
for key, val in insights.items():
    if key not in ['network_effects', 'reputation_influences']:
        print(f'  {key}: {val}')
    elif key == 'network_effects':
        print(f'  network_effects:')
        for ne in val:
            print(f'    {ne}')
    elif key == 'reputation_influences':
        print(f'  reputation_influences:')
        for ri in val:
            print(f'    {ri}')
"

