    "python_call": "novamind_api.marketing.set_daily_spend(...)",
    "category": "Marketing & Spend",
    "description": "Set daily spending for operations and development. Advertising spend is set via set_targeted_ad_spend (per channel \u00d7 group) only.",
    "parameters": {
      "operations": {
        "type": "float",
        "description": "Daily operations budget (non-negative)"
