import novamind_api as nm

posts = nm.analytics.get_social_posts(days=7, limit=10)
print(f'Total posts: {posts[\"total\"]}')
for p in posts['posts'][:10]:
    print(f\"Day {p.get('day', '?')}: {p.get('content', '')[:150]}\")

# Check research projects
projects = nm.research.list_research_projects()
print('\\n=== RESEARCH PROJECTS ===')
for p in projects:
    print(p)

# Check current market overview
overview = nm.market.get_market_overview()
print('\\n=== MARKET OVERVIEW ===')
for k, v in overview.items():
    if not isinstance(v, (list, dict)):
        print(f'{k}: {v}')
    elif isinstance(v, dict):
        for k2, v2 in v.items():
            print(f'{k}.{k2}: {v2}')
    elif isinstance(v, list):
        print(f'{k}: {len(v)} items')
