arguments.command:
./novamind-operation python-c "
import novamind_api as nm

# Current day
print(f'Day: {nm.vars.current_day}')

# Group insights for all known groups
for g in ['S1', 'S2', 'S3', 'E1', 'E2', 'E3', 'D_E09']:
    try:
        insights = nm.market.get_group_insights(g)
        print(f'\n=== {g} ===')
        for k, v in insights.items():
            if k not in ['referral_rates', 'reputation_influence']:
                print(f'  {k}: {v}')
            elif k == 'referral_rates':
                print(f'  referral_rates: (showing non-zero)')
                for src, targets in v.items():
                    for tgt, rate in targets.items():
                        if rate > 0:
                            print(f'    {src} -> {tgt}: {rate:.4f}')
            elif k == 'reputation_influence':
                print(f'  reputation_influence: (showing non-zero)')
                for src, targets in v.items():
                    for tgt, weight in targets.items():
                        if abs(weight) > 0.01:
                            print(f'    {src} -> {tgt}: {weight:.3f}')
    except Exception as e:
        print(f'{g}: ERROR {e}')
"

